def build_agent(sandbox):
    # Vertical beam in the center of the build zone (x=6.05, y=2.085)
    beam1 = sandbox.add_static_beam(x=6.05, y=2.085, width=0.08, height=0.73, angle=0, density=1.5)

    # Horizontal beam at the lower sieve boundary (y=1.92)
    beam2 = sandbox.add_static_beam(x=6.05, y=1.92, width=1.7, height=0.08, angle=0, density=1.5)

    # Horizontal beam at the upper sieve boundary (y=2.41)
    beam3 = sandbox.add_static_beam(x=6.05, y=2.41, width=1.7, height=0.08, angle=0, density=1.5)

    return beam1  # Return the vertical beam as the main structural component

def agent_action(sandbox, agent_body, step_count):
    # Apply forces to guide particles into correct zones
    if step_count % 32 != 0:
        return

    # Guide small particles below the lower sieve (y < 1.92)
    for p in sandbox.get_particles_small():
        if p.active and p.position.y > 1.92:
            sandbox.apply_force(p, (0, -10.0))

    # Guide medium particles between the sieves (1.92 <= y <= 2.45)
    for p in sandbox.get_particles_medium():
        if p.active and p.position.y > 2.45:
            sandbox.apply_force(p, (0, -10.0))
